    let ax1 = locker.stow(locker: ax0, load: 12);
    let ax = locker.stow(locker: ax1, load: 9);

    let bay0 = locker.arrive("bay");
    let bay1 = locker.stow(locker: bay0, load: 30);
    let bay = locker.stow(locker: bay1, load: 25);

    let cod0 = locker.arrive("cod");
