use harbor.signal;

pub fn entries() -> String {
    let signals = signal.sequence();
    var rendered: List<String> = [];
    var i = 0;

    while i < signals.len() {
        let entry = match signals.get(i) {
            Some(signal.Signal.Calm) => "calm",
            Some(signal.Signal.Gale(speed)) => "gale:".concat(speed.to_text()),
            Some(signal.Signal.Fog(density)) => "fog:".concat(density),
            None => "",
        };
        rendered.push(entry);
        i = i + 1;
    }

    rendered.join(";")
}

